# set.py
import os

def init_structure():
    base_path = os.getcwd()
    print(f"📁 Initializing empty boxes under: {base_path}")

    structure = {'api': ['.env', 'terminal_workflow.py'], 'schemas': ['knowledge_package.py'], 'collectors': ['__init__.py', 'base_collector.py', 'manager.py'], 'github': ['__init__.py', 'repository.py', 'issue.py', 'release.py', 'commit.py'], 'qiita': ['__init__.py', 'article.py'], 'huggingface': [], 'analyzers': ['terminal_engine.py'], 'core': ['knowledge_searcher.py', 'ofa_planner.py'], 'data': ['agent_brain.db'], 'knowledge': [], 'html': [], 'css': [], 'terminal': [], 'ts_layer': [], 'handlers': ['handler.ts'], 'frontend': [], 'components': []}

    for folder, files in structure.items():
        if folder == "root":
            target_dir = base_path
        else:
            target_dir = os.path.join(base_path, folder.replace("/", os.sep))

        os.makedirs(target_dir, exist_ok=True)

        for f in files:
            file_path = os.path.join(target_dir, f)
            if not os.path.exists(file_path):
                with open(file_path, "w", encoding="utf-8") as file:
                    file.write("")
                print(f"  📄 Created Empty: {os.path.relpath(file_path, base_path)}")

    print("✅ Setup Completed successfully!")

if __name__ == "__main__":
    init_structure()

